/* Spicy Eel 22 by shadowmurphy — https://uiverse.io/shadowmurphy/spicy-eel-22 */
.card {
  width: 350px;
  height: 150px;
  background: #262626;
  border-radius: 10px;
  border: 1px solid #3F3F40;
}

a {
  text-decoration: none;
}

header, footer, main {
  display: flex;
  align-items: center;
}

header {
  justify-content: space-between;
  margin: 20px;
  color: #BDBFB7;
}

header a {
  font-size: 15px;
  cursor: pointer;
  color: #BDBFB7
}

main {
  justify-content: flex-start;
  margin: 20px;
}

main p {
  color: white;
  font-weight: 600;
}

main a {
  color: #BDBFB7;
  font-weight: 100;
}

footer {
  margin: 20px;
  font-size: 15px;
  gap: 5px;
}

footer a {
  color: #2CAD3D;
  font-weight: 600;
}

footer p {
  color: white;
}
